import{_ as n,o as i,c as a,a4 as t}from"./chunks/framework.B-wJupoK.js";const e="/assets/image-20241226195728205.D0RLDd6W.png",l="/assets/image-20241226195844696.CeB68bse.png",p="/assets/PixPin_2024-12-26_20-02-31.ClMrekaY.gif",r="/assets/PixPin_2024-12-26_21-05-37.Cus8OcKq.gif",m=JSON.parse('{"title":"HarmonyOS Next 弹窗系列教程（1）","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS Next 弹窗系列教程/HarmonyOS Next 弹窗系列教程（1）/HarmonyOS Next 弹窗系列教程（1）.md","filePath":"鸿蒙开发技巧/HarmonyOS Next 弹窗系列教程/HarmonyOS Next 弹窗系列教程（1）/HarmonyOS Next 弹窗系列教程（1）.md","lastUpdated":1748912459000,"__rawMarkdown":"# HarmonyOS Next 弹窗系列教程（1）\\n\\n## 弹窗的介绍\\n\\n### 弹窗概述\\n\\n弹窗一般指打开应用时自动弹出或者用户行为操作时弹出的UI界面，用于短时间内展示用户需关注的信息或待处理的操作。\\n\\n比如以下这些效果：\\n\\n![image-20241226195728205](HarmonyOS%20Next%20%E5%BC%B9%E7%AA%97%E7%B3%BB%E5%88%97%E6%95%99%E7%A8%8B%EF%BC%881%EF%BC%89.assets/image-20241226195728205.png)\\n\\n\\n\\n### 弹窗的种类\\n\\n根据用户交互操作场景，弹窗可分为**模态弹窗**和**非模态弹窗**两种类型，其区别在于用户是否必须对其做出响应。\\n\\n- **模态弹窗：** 为强交互形式，会中断用户当前的操作流程，要求用户必须做出响应才能继续其他操作，通常用于需要向用户传达重要信息的场景。\\n- **非模态弹窗：** 为弱交互形式，不会影响用户当前操作行为，用户可以不对其进行回应，通常都有时间限制，出现一段时间后会自动消失。一般用于告诉用户信息内容外还需要用户进行功能操作的场景。\\n\\n\\n\\n### 模态弹窗\\n\\n为强交互形式，会中断用户当前的操作流程，要求用户必须做出响应才能继续其他操作，通常用于需要向用户传达重要信息的场景。![image-20241226195844696](HarmonyOS%20Next%20%E5%BC%B9%E7%AA%97%E7%B3%BB%E5%88%97%E6%95%99%E7%A8%8B%EF%BC%881%EF%BC%89.assets/image-20241226195844696.png)\\n\\n### 非模态弹窗\\n\\n![PixPin_2024-12-26_20-02-31](HarmonyOS%20Next%20%E5%BC%B9%E7%AA%97%E7%B3%BB%E5%88%97%E6%95%99%E7%A8%8B%EF%BC%881%EF%BC%89.assets/PixPin_2024-12-26_20-02-31.gif)\\n\\n\\n\\n### 弹窗的分类\\n\\nHarmonyOS Next中将弹窗进行了如下这些分类\\n\\n| 弹窗名称                                                     | 应用场景                                                     |\\n| :----------------------------------------------------------- | :----------------------------------------------------------- |\\n| [弹出框（Dialog）](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/arkts-base-dialog-overview-V5) | 当需要展示用户当前需要或必须关注的信息内容或操作时，例如二次退出应用等，应优先考虑使用此弹出框。 |\\n| [菜单控制（Menu）](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/arkts-popup-and-menu-components-menu-V5) | 当需要给指定的组件绑定用户可执行的操作时，例如长按图标展示操作选项等，应优先考虑使用此弹窗。 |\\n| [气泡提示（Popup）](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/arkts-popup-and-menu-components-popup-V5) | 当需要给指定的组件提示时，例如点击一个问号图标弹出一段帮助提示等，应优先考虑使用此弹窗。 |\\n| [绑定模态页面（bindContentCover/bindSheet）](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/arkts-modal-overview-V5) | 当需要新的界面覆盖在旧的界面上，且旧的界面不消失的一种转场方式时，例如缩略图片点击后查看大图等，应优先考虑使用此弹窗。 |\\n| [即时反馈（Toast）](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/arkts-create-toast-V5) | 当需要在一个小的窗口中提供用户当前操作的简单反馈时，例如提示文件保存成功等，应用优先考虑使用此弹窗。 |\\n| [设置浮层（OverlayManager）](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/arkts-create-overlaymanager-V5) | 当需要完全自定义内容、行为、样式时，可以使用浮层将UI展示在页面之上，例如音乐/语音播放悬浮球/胶囊等，应优先考虑使用此弹窗。 |\\n\\n## 弹出框概述\\n\\n用户需在模态弹出框内完成相关交互任务之后，才能退出模态模式。弹出框可以不与任何组件绑定，其内容通常由多种组件组成，如文本、列表、输入框、图片等，以实现布局。ArkUI当前提供了**固定样式**和**自定义**两类弹出框组件。\\n\\n- **自定义弹出框：** 开发者需要根据使用场景，传入自定义组件填充在弹出框中实现自定义的弹出框内容。主要包括基础自定义弹出框 (CustomDialog)、不依赖UI组件的自定义弹出框 (openCustomDialog)。\\n- **固定样式弹出框：** 开发者可使用固定样式弹出框，指定需要显示的文本内容和按钮操作，完成简单的交互效果。主要包括警告弹窗 (AlertDialog)、列表选择弹窗 (ActionSheet)、选择器弹窗 (PickerDialog)、对话框 (showDialog)、操作菜单 (showActionMenu)。\\n\\n## openCustomDialog 使用教程\\n\\n我们分成3步来使用`openCustomDialog`弹窗\\n\\n1. 创建要显示的内容\\n2.  声明UiContext\\n3.  声明promptAction\\n4. 创建要弹窗显示的节点\\n5. 显示弹窗\\n\\n### 创建要显示的内容\\n\\n使用 **@Builder** 修饰的不是普通的函数，而是负责渲染节点的内容构造函数。\\n\\n```typescript\\n@Builder\\nfunction buildText() {\\n  Column() {\\n    Text(\\"自定义标题\\")\\n      .fontSize(50)\\n      .fontWeight(FontWeight.Bold)\\n      .margin({ bottom: 36 })\\n  }.backgroundColor(\'#FFF0F0F0\')\\n}\\n```\\n\\n\\n\\n###  声明UiContext\\n\\n通过**getUIContext()**接口获取UI上下文实例**UIContext**对象\\n\\n```typescript\\nlet uiContext = this.getUIContext();\\n```\\n\\n###  声明promptAction\\n\\n**promptAction**用于创建并显示文本提示框、对话框和操作菜单。\\n\\n```typescript\\nlet promptAction = uiContext.getPromptAction();\\n```\\n\\n### 创建要弹窗显示的节点\\n\\n**omponentContent**表示组件内容的实体封装，其对象支持在非UI组件中创建与传递，便于开发者对弹窗类组件进行解耦封装\\n\\nwrapBuilder是一个全局函数，功能是用来封装全局@Builder，方便@Builder传递和调用\\n\\n```typescript\\nlet contentNode = new ComponentContent(uiContext, wrapBuilder(buildText));\\n```\\n\\n### 显示弹窗\\n\\n最后，调用的promptAction的openCustomDialog方法，传入contentNode便可实现弹窗效果\\n\\n```typescript\\npromptAction.openCustomDialog(contentNode);\\n```\\n\\n\\n\\n![PixPin_2024-12-26_21-05-37](HarmonyOS%20Next%20%E5%BC%B9%E7%AA%97%E7%B3%BB%E5%88%97%E6%95%99%E7%A8%8B%EF%BC%881%EF%BC%89.assets/PixPin_2024-12-26_21-05-37.gif)\\n\\n### 完整代码\\n\\n```typescript\\nimport { ComponentContent } from \'@kit.ArkUI\';\\n\\n\\n@Builder\\nfunction buildText() {\\n  Column() {\\n    Text(\\"自定义标题\\")\\n      .fontSize(50)\\n      .fontWeight(FontWeight.Bold)\\n      .margin({ bottom: 36 })\\n  }.backgroundColor(\'#FFF0F0F0\')\\n}\\n\\n@Entry\\n@Component\\nstruct Index {\\n  build() {\\n    Row() {\\n      Column() {\\n        Button(\\"click me\\")\\n          .onClick(() => {\\n            let uiContext = this.getUIContext();\\n            let promptAction = uiContext.getPromptAction();\\n            let contentNode = new ComponentContent(uiContext, wrapBuilder(buildText));\\n            promptAction.openCustomDialog(contentNode);\\n          })\\n      }\\n      .width(\'100%\')\\n      .height(\'100%\')\\n    }\\n    .height(\'100%\')\\n  }\\n}\\n```\\n\\n\\n\\n## 参考链接\\n\\n1. [wrapBuilder](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V13/arkts-wrapbuilder-V13)\\n2. [ComponentContent](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V13/js-apis-arkui-componentcontent-V13)\\n3. [getUIContext](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V13/ts-custom-component-api-V13#getuicontext)\\n4. [getPromptAction](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V13/js-apis-arkui-uicontext-V13#getpromptaction)"}'),h={name:"鸿蒙开发技巧/HarmonyOS Next 弹窗系列教程/HarmonyOS Next 弹窗系列教程（1）/HarmonyOS Next 弹窗系列教程（1）.md"};function o(k,s,d,c,E,g){return i(),a("div",null,[...s[0]||(s[0]=[t("",43)])])}const y=n(h,[["render",o]]);export{m as __pageData,y as default};
